arguments.command:
# Let's write a C# script to parse the binlog using MSBuild's structured logger
mkdir -p /tmp/binlog-reader && cat > /tmp/binlog-reader/Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors
var errors = new List<(string project, string file, int line, int col, string code, string message)>();
build.VisitAllChildren<Error>(e =>
{
    var proj = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent;
    }
    errors.Add((proj, e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? ""));
});

// Collect all warnings
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w =>
{
    var proj = "";
    var node = w.Parent;
    while (node != null)
    {
        if (node is Project p) { proj = p.Name; break; }
        if (node is Target t && t.Project is Project tp) { proj = tp.Name; break; }
        node = node.Parent;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? ""));
});

Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  {e.code}: {e.message}");
        if (!string.IsNullOrEmpty(e.file))
            Console.WriteLine($"    at {e.file}({e.line},{e.col})");
    }
}

Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
foreach (var g in warnings.GroupBy(w => w.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g)
    {
        Console.WriteLine($"  {w.code}: {w.message}");
    }
}

// Show project dependency info - which projects failed
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
build.VisitAllChildren<Project>(p =>
{
    if (!p.Succeeded)
        Console.WriteLine($"  FAILED: {p.Name} (Target: {p.TargetFramework})");
});
EOF

cat > /tmp/binlog-reader/binlog-reader.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.*" />
  </ItemGroup>
</Project>
EOF

