using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show all projects
Console.WriteLine("=== PROJECT STRUCTURE ===");
build.VisitAllChildren<Project>(p =>
{
    Console.WriteLine($"\nProject: {p.Name} (TargetFramework: {p.TargetFramework})");
});

// Show items (package refs, project refs)
Console.WriteLine("\n=== ITEMS ===");
build.VisitAllChildren<AddItem>(ai =>
{
    if (ai.Name == "PackageReference" || ai.Name == "ProjectReference")
    {
        var proj = "";
        var node = ai.Parent;
        while (node != null)
        {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in ai.Children)
        {
            Console.WriteLine($"  [{proj}] {ai.Name}: {child}");
        }
    }
});

// Detailed errors
Console.WriteLine("\n=== DETAILED ERRORS ===");
build.VisitAllChildren<Error>(e =>
{
    Console.WriteLine($"\nError: {e.Code} - {e.Text}");
    Console.WriteLine($"  File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine($"  ProjectFile: {e.ProjectFile}");
});

// Check if any projects depend on the failing project
Console.WriteLine("\n=== PROJECT REFERENCES ===");
build.VisitAllChildren<AddItem>(ai =>
{
    if (ai.Name == "ProjectReference")
    {
        var proj = "";
        var node = ai.Parent;
        while (node != null)
        {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        foreach (var child in ai.Children)
            Console.WriteLine($"  {proj} -> {child}");
    }
});
EOF
