build.VisitAllChildren<Task>(t =>
{
    if (t.Name == "Csc")
    {
        var proj = "";
        var node = t.Parent;
        while (node != null)
        {
            if (node is Project p) { proj = p.Name; break; }
            node = node.Parent;
        }
        if (proj.Contains("Services"))
        {
            Console.WriteLine($"\n[{proj}] Csc task:");
            foreach (var child in t.Children)
            {
                var text = child.ToString();
                if (text.Contains("Newtonsoft") || text.Contains("References") || text.Contains("/reference"))
                    Console.WriteLine($"  {text.Substring(0, Math.Min(300, text.Length))}");
            }
        }
    }
});

